import type {
	ContextInput,
	ContextImage,
} from "../../core/tools/context/contracts";

export const contextPng =
	"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aVZkAAAAASUVORK5CYII=";
// A 1×1 orange JPEG, with optional metadata removed.
export const contextJpeg =
	"";

export function contextImageEvidence(
	device = "ios-a",
	platform: "ios" | "android" = "ios",
	mimeType: ContextImage["mimeType"] = "image/png",
) {
	return {
		kind: "annotation" as const,
		device,
		platform,
		sessionId: `${device}:capture`,
		capturedAt: 123456,
		note: "Improve the contrast.",
		logs: [],
		target: {
			kind: "region" as const,
			reason: "missing-tree",
			rect: { x: 0, y: 0, width: 1, height: 1 },
		},
		image: {
			mimeType,
			width: 1,
			height: 1,
			base64: mimeType === "image/png" ? contextPng : contextJpeg,
		},
	} satisfies ContextInput;
}
